import { useState } from "react";
import { MainBlock, Cart } from "./components";
import "./App.css";

const App = () => {
  const products = [
    {
      title: "Apple",
      icon: "data:image/jpeg;base64,",
      description: "Fruit",
      id: 1,
    },
    {
      title: "Banana",
      icon: "data:image/jpeg;base64,",
      description: "Fruit",
      id: 2,
    },
    {
      title: "Orange",
      icon: "data:image/jpeg;base64,",
      description: "Fruit",
      id: 3,
    },
    {
      title: "Carrot",
      icon: "data:image/jpeg;base64,",
      description: "Vegetable",
      id: 4,
    },
    {
      title: "Tomato",
      icon: "data:image/jpeg;base64,",
      description: "Vegetable",
      id: 5,
    },
    {
      title: "Potato",
      icon: "data:image/jpeg;base64,",
      description: "Vegetable",
      id: 6,
    },
    {
      title: "Milk",
      icon: "data:image/jpeg;base64,",
      description: "Dairy",
      id: 7,
    },
    {
      title: "Cheese",
      icon: "data:image/png;base64,",
      description: "Dairy",
      id: 8,
    },
    {
      title: "Bread",
      icon: "data:image/jpeg;base64,",
      description: "Bakery",
      id: 9,
    },
    {
      title: "Egg",
      icon: "data:image/jpeg;base64,",
      description: "Protein",
      id: 10,
    },
  ];

  const [cart, setCart] = useState([]);

  const addToCart = (product) => {
    setCart((prev) =>
        prev.some((item) => item.id === product.id) ? prev : [...prev, product]
    );
  };

  const removeFromCart = (id) => {
    setCart((prev) => prev.filter((item) => item.id !== id));
  };

  return (
      <div className="container">
        <h1 className="container__title">Products</h1>
        <div className="grid">
          {products.map((product) => (
              <MainBlock
                  key={product.id}
                  {...product}
                  buttonText="Добавить в корзину"
                  onClick={() => addToCart(product)}
              />
          ))}
        </div>

        <Cart items={cart} onRemove={removeFromCart} />
      </div>
  );
};

export default App;